+    /// <summary>已验证结果缓存 5 分钟；未验证的 30 秒后重试。</summary>
+    private static readonly TimeSpan TermsrvVerifiedTtl = TimeSpan.FromMinutes(5);
+
+    private static readonly TimeSpan TermsrvUnverifiedTtl = TimeSpan.FromSeconds(30);
