+            if (process is null)
+            {
+                return -1;
+            }
+
+            // 输出是 UTF-16/本地化文本，不值得解析；只要它跑完，看退出码即可。
+            _ = process.StandardOutput.ReadToEndAsync();
+            _ = process.StandardError.ReadToEndAsync();
