+            return process.ExitCode;
+        }
+        catch (Exception exception) when (exception is InvalidOperationException
+                                              or System.ComponentModel.Win32Exception
+                                              or IOException)
+        {
+            Logger.LogWarning(exception, "运行 sfc /verifyfile 失败。");
+            return -1;
+        }
+    }
