+                    hits.Add(new ToolPersistenceHit(
+                        "run",
+                        $"{label}\\{path} → {name}",
+                        data,
+                        RegistryRoot: root == Registry.CurrentUser ? "HKCU"
+                            : root == Registry.Users ? "HKU"
+                            : "HKLM",
+                        RegistryPath: path,
+                        ValueName: name));
